import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, texture, mix, mul, add } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Root group for this node
  const group = new THREE.Group();

  // Geometry: simple plane (2x2 units, centered)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load the orb-decor image
  let material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    side: THREE.DoubleSide,
    transparent: true,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Load texture and apply with grain overlay
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    // Set texture properties
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;

    // Create shader nodes for texture + grain
    const uvNode = uv();
    const baseTexture = texture(tex, uvNode);

    // Subtle grain: use a pseudo-random pattern based on UV coords
    const grainAmount = mul(
      add(
        mul(
          mix(
            mul(uvNode.x, 100.0),
            mul(uvNode.y, 100.0),
            0.5
          ),
          0.1
        ),
        0.02
      ),
      vec3(1.0)
    );

    // Blend base texture with grain
    const finalColor = add(
      baseTexture,
      mul(grainAmount, 0.08)
    );

    // Update material with color nodes
    material.colorNode = finalColor;
    material.alphaNode = baseTexture.a;
    material.needsUpdate = true;
  });

  // Apply scene position (adapter will handle, but we set it here for consistency)
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  } else {
    group.position.set(0, -2.85, 0.2);
  }

  if (config.rotation) {
    group.rotation.copy(config.rotation);
  }

  if (config.scale) {
    group.scale.copy(config.scale);
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.rotation);
    gsap.killTweensOf(mesh.scale);
  };

  // Setup handlers object for potential future interactions
  group.userData.handlers = {};

  return group;
}
